const panel=document.querySelector('#utilityPanel');let selectedHome='MERIDIAN FC',selectedAway='ATHLETIC CLUB';function showPanel(type){if(type==='home'){panel.classList.add('hidden');return}panel.classList.remove('hidden');if(type==='clubs')panel.innerHTML='<h2>CHOOSE YOUR COLORS</h2><p>Select a side for your next fixture. Every club has its own identity and match kit.</p><div class="club-chips">'+['Meridian FC','Athletic Club','Real Madrid','Barcelona','Man City','Liverpool','Bayern','Paris SG','Arsenal','Juventus'].map((n,i)=>`<button class="club-chip ${i<2?'selected':''}" data-club="${n}">${n}</button>`).join('')+'</div>';if(type==='career')panel.innerHTML='<h2>YOUR STORY STARTS HERE</h2><p>Build a club from the ground up. Shape your squad, find your formation and chase the silverware. Career mode is coming to the next season update.</p><button class="formation-chip selected">CONTINUE AS MERIDIAN FC　↗</button>';if(type==='training')panel.innerHTML='<h2>TRAINING GROUND</h2><p>Practice the essentials before kickoff. Use <b>WASD</b> to move, <b>F</b> to shoot, <b>SPACE</b> to pass, <b>SHIFT</b> to sprint and <b>E</b> to switch player.</p><div class="club-chips"><button class="formation-chip selected">FREE PRACTICE</button><button class="formation-chip">FINISHING</button><button class="formation-chip">PASSING</button></div>';if(type==='settings')panel.innerHTML='<h2>MATCH SETTINGS</h2><p>Set the scene for your next match.</p><div class="club-chips"><button class="formation-chip selected" data-weather="CLEAR">☀ CLEAR</button><button class="formation-chip" data-weather="CLOUDY">☁ CLOUDY</button><button class="formation-chip" data-weather="RAIN">☂ RAIN</button><button class="formation-chip" data-weather="DAY">DAYLIGHT</button><button class="formation-chip" data-weather="NIGHT">NIGHT</button></div><p style="margin-top:13px;font-size:10px">FORMATION　 <button class="formation-chip selected">4-3-3</button> <button class="formation-chip">4-4-2</button> <button class="formation-chip">4-2-3-1</button></p>';panel.querySelectorAll('[data-club]').forEach(b=>b.onclick=()=>{panel.querySelectorAll('[data-club]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedHome=b.dataset.club});panel.querySelectorAll('[data-weather]').forEach(b=>b.onclick=()=>{weather=b.dataset.weather;panel.querySelectorAll('[data-weather]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');applyWeather()})}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');showPanel(b.dataset.panel)}));function applyWeather(){if(weather==='NIGHT'){scene.background.set(0x07101d);scene.fog.color.set(0x07101d);keyLight.intensity=1.2;fill.intensity=1.5}else if(weather==='CLOUDY'){scene.background.set(0x53656a);scene.fog.color.set(0x53656a);keyLight.intensity=1.5}else if(weather==='DAY'){scene.background.set(0x7294a0);scene.fog.color.set(0x7294a0);keyLight.intensity=3.8}else{scene.background.set(0x10251f);scene.fog.color.set(0x10251f);keyLight.intensity=3.2}}
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}window.addEventListener('resize',resize);
function animate(now){requestAnimationFrame(animate);let dt=Math.min(.04,(now-last)/1000);last=now;updateGame(dt);if(!matchActive){let t=now*.00015;camera.position.x=Math.sin(t)*2;camera.lookAt(0,0,0);ball.rotation.y+=dt*.4}renderer.render(scene,camera)}requestAnimationFrame(animate);
